# Lesson 1: opening and part 1 (derivatives, motives, exposure, net exposure, four cases).
# Layout rules for these slides live in css/f.css, scoped to the slide ids.


def _F_CELL(c):
    """A table cell: plain text, or (value, how it was computed) shown as a bold value with the calculation under it."""
    return f'<b class="gv">{TX(c[0])}</b><span class="gm">{TX(c[1])}</span>' if isinstance(c, tuple) else TX(c)


def _F_ROWS(head, rows, start=1, cls=''):
    """A table revealed row by row. A cell may be (value, calculation)."""
    h = ''.join(f'<th>{TX(x)}</th>' for x in head)
    b = ''.join(ST(start + i, ''.join(f'<td>{_F_CELL(c)}</td>' for c in r), 'tr') for i, r in enumerate(rows))
    return f'<table class="tbl2 {cls}"><tr>{h}</tr>{b}</table>'


def _F_GRID(head, rows, cls=''):
    """A table whose cells carry their own click: text is static, (n, value) or (n, value, calculation) appears on click n."""
    h = ''.join(f'<th>{TX(x)}</th>' for x in head)
    b = ''
    for r in rows:
        tds = ''
        for c in r:
            if isinstance(c, tuple):
                inner = f'<b class="gv">{TX(c[1])}</b>' + (f'<span class="gm">{TX(c[2])}</span>' if len(c) > 2 else '')
                tds += f'<td>{ST(c[0], inner)}</td>'
            else:
                tds += f'<td>{TX(c)}</td>'
        b += f'<tr>{tds}</tr>'
    return f'<table class="tbl2 steptbl {cls}"><tr>{h}</tr>{b}</table>'


def _F_STEP(n, html):
    return ST(n, TX(html), 'p', 'sp')


def _F_CASE(sid, title, story, qtext, opts, a, why, rem, sol, side=''):
    """A case: the story and a multiple choice question with its formula box, and a solution revealed click by click."""
    q = mc(sid + '-q', qtext, opts, a, why, rot=False, rem=rem)
    S(sid, title, title, f'<div class="qg"><div class="qr"><div class="card qstem"><p>{TX(story)}</p></div>{q}{side}</div><div class="solw card">{sol}</div></div>',
      kick=f'חלק {CUR[0]} · מקרה', cls='qslide')


