S('s-terms2', 'עוד כמה מושגים', 'לפני המקרים: עוד ארבעה מושגים',
  '<p class="lead">' + TX('המקרים הבאים משתמשים במושגים האלה. כאן הגדרה קצרה ודוגמה, ובחלק 2 נרחיב.') + '</p><div class="two4">'
  + DEF('חוזה אקדמה (Forward)', 'הסכם היום על קנייה או מכירה בעתיד, במחיר שנקבע היום. שני הצדדים מחויבים.', 'דנה קונה היום 500,000 דולר לעוד 3 חודשים, בשער 3.55. ביום התשלום השער 3.80? היא משלמת 3.55, וחוסכת $500,000 × 0.25 = 125,000$ ש״ח.', 1, trm='forward')
  + DEF('קונה (Long) ומוכר (Short)', 'מי שמתחייב לקנות בעתיד הוא הקונה בחוזה (Long). מי שמתחייב למכור בעתיד הוא המוכר בחוזה (Short).', 'יבואן שישלם 500,000 דולר קונה חוזה על 500,000 דולר. יצואן שיקבל 300,000 דולר מוכר חוזה על 300,000 דולר.', 2, trm='long')
  + DEF('גזבר (Treasurer)', 'מי שמנהל בחברה את הכסף: מזומנים, הלוואות, מטבע וגידור.', 'לחברה תשלום של 500,000 דולר. הגזבר מחליט לגדר 400,000 דולר, כלומר $400,000 ÷ 500,000 = 80%$, ובוחר מול איזה בנק.', 3)
  + DEF('מנדט (Mandate)', 'ההרשאה שנותנת ההנהלה לגזבר: מה מותר לעשות, ובאיזה היקף.', '״מותר לגדר עד 100% מהחשיפה נטו.״ חשיפה נטו של 100,000 דולר: מותר חוזה עד 100,000 דולר. כל מה שמעבר לזה כבר אינו גידור.', 4) + '</div>', kick='חלק 1 · מושגים')

# ---------------------------------------------------------------- four cases
_OPT3 = ['מוסיף ערך', 'מיותר', 'מסוכן']

_F_CASE('c-1', 'מקרה 1: היבואנית', 'דנה מוכרת רהיטים, וכל ההכנסות שלה בשקלים: 1,950,000 ש״ח. בעוד 3 חודשים היא תשלם לספק 500,000 דולר. הבנק מציע לה חוזה אקדמה (Forward): לקנות היום 500,000 דולר לעוד 3 חודשים, בשער 3.55. <b>נדרש:</b> האם החוזה מוסיף ערך לעסק, מיותר או מסוכן? נמקו.',
        'מה החוזה עושה לעסק של דנה?', _OPT3, 0, 'יש חשיפה ברורה, והחוזה מחזיר את דנה לעסק שלה: רהיטים.',
        'רווח = הכנסות בשקלים − תשלום בדולרים × שער. בחוזה, השער ידוע מראש.',
        _F_STEP(1, '<b>שלב 1, ממה דנה רוצה להרוויח?</b> מרהיטים: היא קונה בזול ומוכרת ביוקר. בזה היא מומחית.')
        + _F_STEP(2, '<b>שלב 2, ההימור שלא בחרה:</b> בלי חוזה, הרווח תלוי בשער ביום התשלום.')
        + _F_GRID(['שער ביום התשלום', 'רווח בלי חוזה (ש״ח)', 'רווח עם חוזה ב-3.55 (ש״ח)'], [
            ['<b>3.20</b>', (3, '350,000', '$1,950,000 − 500,000 × 3.20$'), (7, '175,000', '$1,950,000 − 500,000 × 3.55$')],
            ['<b>3.80</b>', (4, '50,000', '$1,950,000 − 500,000 × 3.80$'), (7, '175,000', 'אותו חישוב')],
            ['<b>4.00</b>', (5, '$-50,000$', '$1,950,000 − 500,000 × 4.00$'), (7, '175,000', 'אותו חישוב')]], 'f-ct')
        + _F_STEP(6, '<b>שלב 3, החוזה:</b> השער נקבע היום על 3.55. העלות: $500,000 × 3.55 = 1,775,000$ ש״ח, בכל שער.')
        + _F_STEP(8, '<b>שלב 4, המחיר:</b> אם הדולר יורד ל-3.20, היא מוותרת על רווח נוסף של $350,000 − 175,000 = 175,000$ ש״ח. זה מחיר הוודאות.')
        + _F_STEP(9, '<b>מסקנה:</b> מוסיף ערך. הרווח תלוי רק ברהיטים, ודנה נשארת סוחרת רהיטים, לא סוחרת דולרים.'))

# ---------------------------------------------------------------- a real world example: a currency-hedged fund
_t, _n = GT(['', 'קרן ללא גידור', 'קרן מגודרת מט״ח'], [
    ['<b>היום</b>', ('100,000 דולר', '$350,000 ÷ 3.50$'), ('100,000 דולר', '$350,000 ÷ 3.50$')],
    ['<b>המניות עלו ב-8%</b>', ('108,000 דולר', '$100,000 × 1.08$'), ('108,000 דולר', '$100,000 × 1.08$')],
    ['<b>הדולר ירד ל-3.15</b>', ('340,200 ש״ח', '$108,000 × 3.15$'), ('340,200 ש״ח', '$108,000 × 3.15$')],
    ['<b>תוצאת החוזה</b>', 'אין חוזה', ('$+35,000$ ש״ח', '$100,000 × (3.50 − 3.15)$')],
    ['<b>בסוף השנה</b>', ('340,200 ש״ח', 'הפסד של 2.8%'), ('375,200 ש״ח', 'רווח של 7.2%')]])
S('s-etf', 'מהעולם האמיתי: קרן מגודרת', 'מהעולם האמיתי: קרן סל מגודרת מטבע חוץ (Currency-hedged)',
  '<div class="card qstem"><p>' + TX('משקיע ישראלי משקיע 350,000 ש״ח במניות בארה״ב, דרך קרן סל. השער היום 3.50. לאורך זמן, למניות יש תשואה צפויה חיובית. לשער הדולר אין מגמה צפויה ברורה, אבל הוא תנודתי. המשקיע רוצה את המניות, בלי ההימור על הדולר. <b>נדרש:</b> השוו את התוצאה בשקלים בסוף השנה, בקרן ללא גידור ובקרן מגודרת, אם המניות עולות ב-8% והדולר יורד ל-3.15.') + '</p></div>'
  + '<div class="row eq2 top f-gap"><div class="col">' + _t + '</div><div class="col">'
  + DEF('קרן סל מגודרת מט״ח (Currency-hedged)', 'מט״ח: מטבע חוץ. קרן סל (Exchange Traded Fund, ETF): קרן שנסחרת בבורסה כמו מניה. הקרן המגודרת קונה מניות בדולרים, ובמקביל מוכרת (Short) חוזי אקדמה (Forward) על הדולר.', 'בבורסה בתל אביב נפוצות קרנות כאלה על מדדי מניות בארה״ב. הן נקראות גם ״מנוטרלות מט״ח״.', _n, cls='mini')
  + BAND('dg', 'כמו אצל דנה: המשקיע רוצה להרוויח מהמניות, לא מהשער. החוזה מבטל בקירוב את השפעת הדולר.', _n + 1)
  + BAND('note', 'המספרים להמחשה. לגידור יש עלות, שתלויה בהפרש הריביות בין ישראל לארה״ב. ואם הדולר עולה, הקרן המגודרת מוותרת על הרווח מהשער.', _n + 2) + '</div></div>', kick='חלק 1 · מהעולם האמיתי')

_t, _n = GT(['השפעה על הרווח (ש״ח)', 'הדולר עולה ב-0.10', 'הדולר יורד ב-0.10'], [
    ['<b>מההכנסות</b>', ('$+100,000$', '$1,000,000 × 0.10$'), ('$-100,000$', '$1,000,000 × 0.10$')],
    ['<b>מההוצאות</b>', ('$-100,000$', '$1,000,000 × 0.10$'), ('$+100,000$', '$1,000,000 × 0.10$')],
    ['<b>סך הכול</b>', ('0', '$100,000 − 100,000$'), ('0', '$100,000 − 100,000$')]], 3, 'f-ct')
_F_CASE('c-2', 'מקרה 2: הכנסות והוצאות באותו מטבע', 'לחברה ישראלית הכנסות של 1,000,000 דולר והוצאות של 1,000,000 דולר, באותו חודש. הגזבר מציע למכור חוזה אקדמה (Forward) על 1,000,000 דולר, ״כדי להגן על ההכנסות״. <b>נדרש:</b> האם החברה צריכה את החוזה, במצב שלה היום? נמקו.',
        'האם החברה צריכה את החוזה, במצב שלה היום?', _OPT3, 1, 'החשיפה נטו היום אפס. אין סיכון שהחוזה יכול להקטין.',
        'חשיפה נטו = הכנסות בדולרים − הוצאות בדולרים, באותו מועד.',
        _F_STEP(1, '<b>שלב 1, החשיפה נטו:</b> $1,000,000 − 1,000,000 = 0$ דולר.')
        + _F_STEP(2, '<b>שלב 2, מה קורה לרווח בלי חוזה?</b> כל שינוי בשער פוגע בצד אחד ומפצה בצד השני.') + _t
        + _F_STEP(_n, '<b>שלב 3, מי כבר מגן?</b> גידור טבעי (Natural hedge). ההוצאות בדולרים עושות בדיוק את מה שהחוזה היה אמור לעשות, ובחינם.')
        + _F_STEP(_n + 1, '<b>שלב 4, הטעות של הגזבר:</b> הוא הסתכל רק על ההכנסות. גידור שוקלים על החשיפה נטו, לא על שורה אחת בדוח.')
        + _F_STEP(_n + 2, '<b>מסקנה:</b> מיותר. אם בעתיד ההכנסות וההוצאות ייפרדו, בסכום או במועד, תיווצר חשיפה נטו, ואז מחשבים מחדש.'))

_F_CASE('c-3', 'מקרה 3: חשיפה קטנה', 'לעסק קטן תשלום של 5,000 דולר בעוד חודש. נניח שתנודה סבירה בשער, בחודש אחד, היא 0.20 ש״ח לדולר. פתיחת קו מול הבנק והטיפול בחוזה אקדמה (Forward) יעלו לעסק 3,000 ש״ח. <b>נדרש:</b> האם כדאי לעסק לגדר את התשלום בחוזה? נמקו.',
        'מה החוזה עושה לעסק?', _OPT3, 1, 'העלות גבוהה מהסיכון שהחוזה מסיר.',
        'הסיכון = תשלום בדולרים × תנודה בשער. משווים אותו לעלות החוזה.',
        _F_ROWS(['מה מחשבים', 'הערך', 'איך ולמה'], [
            ['<b>התשלום</b> (דולר)', '5,000', 'נתון'],
            ['<b>תנודה סבירה בשער</b>', '0.20 ש״ח', 'הנחה, לחודש אחד'],
            ['<b>הסיכון</b> (ש״ח)', '1,000', '$5,000 × 0.20$: סכום שהעסק יכול לספוג'],
            ['<b>עלות החוזה</b> (ש״ח)', '3,000', 'בוודאות, גם אם השער לא זז'],
            ['<b>ההשוואה</b>', '$3,000 > 1,000$', 'העלות גדולה פי 3 מהסיכון']], 1, 'mtab f-ct')
        + _F_STEP(6, '<b>מסקנה:</b> מיותר. לא כל חשיפה שווה טיפול. גידור שווה את עלותו רק כשהסיכון גדול ביחס לרווח, ולא כשהוא קטן מעלות החוזה.')
        + MEME('sleep', 'עסק עם סיכון של 1,000 ש״ח', 'ישן טוב, ולא משלם 3,000 בשביל זה', 7))

_F_CASE('c-4', 'מקרה 4: הגזבר הנלהב', 'יבואן ישלם לספק 100,000 דולר בעוד 3 חודשים. הגזבר בטוח שהדולר יעלה, ולכן קונה חוזי אקדמה (Forward) על 300,000 דולר. <b>נדרש:</b> מה החוזים עושים לעסק? מה יקרה אם הדולר יירד ב-0.20 ש״ח?',
        'מה החוזה עושה לעסק?', _OPT3, 2, 'רק 100,000 דולר הם גידור. השאר הוא הימור.',
        'חלק ההימור = סכום החוזים − החשיפה נטו. ההפסד בו = חלק ההימור × השינוי בשער.',
        _F_ROWS(['מה מחשבים', 'הערך', 'איך ולמה'], [
            ['<b>החשיפה</b> (דולר)', '100,000', 'התשלום לספק'],
            ['<b>החוזים</b> (דולר)', '300,000', 'מה שהגזבר קנה'],
            ['<b>חלק הגידור</b> (דולר)', '100,000', 'מכסה את התשלום, ולא יותר'],
            ['<b>חלק ההימור</b> (דולר)', '200,000', '$300,000 − 100,000$: לא מגן על שום דבר'],
            ['<b>הדולר יורד ב-0.20</b> (ש״ח)', '$-40,000$', '$200,000 × 0.20$: הפסד על החלק העודף']], 1, 'mtab f-ct')
        + _F_STEP(6, '<b>תרחיש הפוך:</b> אם הדולר עולה ב-0.20, החלק העודף מרוויח 40,000 ש״ח. גם זה לא גידור. זה הימור שהצליח.')
        + _F_STEP(7, '<b>מסקנה:</b> מסוכן. מנדט כמו ״עד 100% מהחשיפה נטו״ היה עוצר את הגזבר ב-100,000 דולר.')
        + TOON('dice', 'הגזבר: ״זה לא הימור, אני בטוח.״ הדולר: ״בטוח?״', 8))

